contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0), "recipient must not be zero");
        require(amount > 0, "amount must be greater than zero");

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(recipient);

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 senderAfter = c.balanceOf(address(this));
        uint256 recipientAfter = c.balanceOf(recipient);

        assert(
            reverted ||
                (senderBefore >= amount &&
                    senderAfter == senderBefore - amount &&
                    recipientAfter == recipientBefore + amount)
        );
    }

    receive() external payable {}
}

