contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount > 0, "amount must be positive");

        uint256 senderBalBefore = c.balanceOf(address(this));
        uint256 recipientBalBefore = c.balanceOf(address(0xdead));

        bool reverted;
        try c.transfer(address(0xdead), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 senderBalAfter = c.balanceOf(address(this));
            uint256 recipientBalAfter = c.balanceOf(address(0xdead));

            assert(senderBalBefore >= amount);
            assert(senderBalAfter == senderBalBefore - amount);
            assert(recipientBalAfter == recipientBalBefore + amount);
        } else {
            assert(c.balanceOf(address(this)) == senderBalBefore);
            assert(c.balanceOf(address(0xdead)) == recipientBalBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount > 0, "amount must be positive");

        uint256 senderBalBefore = c.balanceOf(address(this));
        uint256 recipientBalBefore = c.balanceOf(address(0xdead));
        uint256 rewardBefore = c.txReward(address(0xdead));

        bool reverted;
        try c.transfer(address(0xdead), amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(c.balanceOf(address(this)) == senderBalBefore && c.balanceOf(address(0xdead)) == recipientBalBefore && c.txReward(address(0xdead)) == rewardBefore);
        } else {
            uint256 senderBalAfter = c.balanceOf(address(this));
            uint256 recipientBalAfter = c.balanceOf(address(0xdead));
            uint256 rewardAfter = c.txReward(address(0xdead));
            assert(senderBalBefore >= amount && senderBalBefore - senderBalAfter == amount && recipientBalAfter >= recipientBalBefore + amount && recipientBalAfter - recipientBalBefore - amount == rewardAfter - rewardBefore);
        }
    }

    receive() external payable {}
}

