contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address owner, address spender, address recipient, uint256 amount) public {
        require(owner != address(0), "zero owner");
        require(spender != address(0), "zero spender");
        require(recipient != address(0), "zero recipient");
        require(amount > 0 && amount <= 10000000 * 1e18, "amount range");
        require(spender == address(this), "spender must be test contract");

        // The test contract must be the owner so it can approve and then transfer
        // Actually to make spender==this, we need owner to be this as well
        // Since run is called by the test contract, msg.sender for c calls is this
        // So owner must be this for approve to work
        require(owner == address(this), "owner must be test contract");

        c.approve(spender, amount);
        uint256 allowanceBefore = c.allowance(owner, spender);

        bool reverted;
        try c.transferFrom(owner, recipient, amount) {
            reverted = false;
