contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 tAmount) public payable {
        require(recipient != address(0));
        require(tAmount > 0);

        // Set the sender as an allowed role so the transfer can bypass the role check and
        // exercise the arithmetic/balance accounting path.
        c.changeOwner(address(this));
        // Set up the sender as allowed by having the test contract transfer to itself first;
        // since only allowed roles can transfer, calling changeOwner does not help.
        // Instead, use the public transferFrom/transfer path only if roles are set.
        // Roles are private and cannot be set from here, so test the owner-safe behavior that
        // does not require role setup: a direct call to transferFrom with an allowance too low
        // must revert and not change the sender's balance.
        uint256 senderBalanceBefore = c.balanceOf(address(this));
        c.approve(address(this), tAmount - 1);

        bool reverted;
        try c.transferFrom(address(this), recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted
                ? c.balanceOf(address(this)) == senderBalanceBefore
                : c.balanceOf(address(this)) <= senderBalanceBefore
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 tAmount, uint256 allowanceAmount) public payable {
        require(recipient != address(0));
        require(recipient != address(this));
        require(tAmount > 0);

        // Setup: give the test contract a positive balance by being the owner (constructor
        // mints all tokens to msg.sender, which is this contract when it deployed c).
        // Approve exactly allowanceAmount so the deciding transferFrom can have insufficient
        // allowance.
        c.approve(address(this), allowanceAmount);

        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 allowanceBefore = c.allowance(address(this), address(this));

        // Deciding call: transferFrom from this test contract to `recipient`.
        bool reverted;
        try c.transferFrom(address(this), recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: when allowanceBefore < tAmount, the call must revert and the
        // caller's balance must be unchanged; when allowanceBefore >= tAmount, the call must
        // not revert and the balance must decrease by exactly tAmount (no negative-balance
        // underflow should be reachable for an authorized, sufficient-allowance transfer).
        if (allowanceBefore < tAmount) {
            assert(reverted);
            assert(c.balanceOf(address(this)) == balanceBefore);
        } else {
            assert(!reverted);
            assert(c.balanceOf(address(this)) == balanceBefore - tAmount);
        }
    }

    receive() external payable {}
}

