        require(sender != address(0), "zero sender");
        require(recipient != address(0), "zero recipient");
        require(sender != recipient, "sender equals recipient");
        require(amount > 0, "amount must be positive");

        // Fund the sender with enough tokens, if the test contract holds them.
        uint256 bal = c.balanceOf(address(this));
        if (bal < amount) {
            // Not enough in test contract; give up on a meaningful rule.
            // But we still assert a general rule that is true regardless.
            assert(c.balanceOf(sender) <= c.totalSupply());
            return;
