        // Instead, use transfer to test the rule (same _transfer logic).
        uint256 testBalBefore = c.balanceOf(address(this));
        bool ok = c.transfer(recipient, amount);
        uint256 senderBalAfter = c.balanceOf(address(this));
        uint256 recipientBalAfter = c.balanceOf(recipient);

        assert(ok && senderBalAfter + amount <= testBalBefore && recipientBalAfter >= recipientBalBefore + amount);
    }

    receive() external payable {}
}

